loadTableFromCsvFile <- function(csvFileName, verbose=FALSE, ...){
	#add zcat if the file extention is gz
	input <- paste0(ifelse(str_sub(csvFileName,-2)=='gz','zcat
',''),csvFileName) 
	#read the file
	dt <- fread(input,...)
	if(verbose) cat('Loaded',csvFileName,'\n')
	return(dt)
}




